<?php
namespace App\Http\Controllers\Storefront\Commerce;
use App\Actions\Cart\{AddToCart,GetCurrentCart,UpdateCartItem}; use App\Http\Controllers\Controller; use App\Http\Requests\Storefront\Commerce\{AddToCartRequest,UpdateCartItemRequest}; use App\Models\{Cart,CartItem,Product,ProductVariant}; use Illuminate\Http\RedirectResponse; use Inertia\{Inertia,Response};
class CartController extends Controller { public function show(GetCurrentCart $current):Response{$cart=$current->handle(request()->user(),request()->session()->getId());return Inertia::render('Storefront/Cart/Show',['cart'=>$cart->load('items.product','items.variant')]);} public function store(AddToCartRequest $request,Cart $cart,AddToCart $action):RedirectResponse{$data=$request->validated();$action->handle($cart,Product::findOrFail($data['product_id']),isset($data['product_variant_id'])?ProductVariant::findOrFail($data['product_variant_id']):null,$data['quantity']);return back()->with('success','Cart updated.');} public function update(UpdateCartItemRequest $request,CartItem $item,UpdateCartItem $action):RedirectResponse{$action->handle($item,$request->integer('quantity'));return back()->with('success','Cart updated.');} public function destroy(CartItem $item):RedirectResponse{$this->authorize('update',$item->cart);$item->delete();return back()->with('success','Item removed.');} }
